<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides partner api key behavior within the WorkIntel application. */ class PartnerApiKey extends Model{public $timestamps=false;protected $hidden=['token_hash'];protected $fillable=['uuid','partner_account_id','created_by','name','prefix','token_hash','scopes','last_used_at','last_used_ip','expires_at','revoked_at','created_at'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['scopes'=>'array','last_used_at'=>'datetime','expires_at'=>'datetime','revoked_at'=>'datetime','created_at'=>'datetime'];}/** Handles the account operation for the current WorkIntel workflow. */ public function account():BelongsTo{return $this->belongsTo(PartnerAccount::class,'partner_account_id');}/** Handles the allows operation for the current WorkIntel workflow. */ public function allows(string $scope):bool{$s=$this->scopes??[];return in_array('*',$s,true)||in_array($scope,$s,true);}}
